const T = aide.THREE;
aide.say('How a four stroke engine works. Pinch Next to step through each stroke.');
const root = new T.Group();
root.position.set(0, 0, -0.18);
aide.scene.add(root);

const steel = new T.MeshStandardMaterial({ color: '#9aa4ad', metalness: 0.55, roughness: 0.4 });
const darkM = new T.MeshStandardMaterial({ color: '#3b4047', metalness: 0.3, roughness: 0.6 });
const glassM = new T.MeshStandardMaterial({ color: '#8fc4ff', transparent: true, opacity: 0.16, roughness: 0.1, metalness: 0.1, side: T.DoubleSide, depthWrite: false });
const blueM = new T.MeshStandardMaterial({ color: '#3a8de0', transparent: true, opacity: 0.55, roughness: 0.8 });
const orangeM = new T.MeshStandardMaterial({ color: '#ff9a2e', transparent: true, opacity: 0.75, emissive: '#ff6a00', emissiveIntensity: 0.7 });
const greyM = new T.MeshStandardMaterial({ color: '#9a9a9a', transparent: true, opacity: 0.5, roughness: 0.9 });
const sparkM = new T.MeshStandardMaterial({ color: '#ffd400', emissive: '#ffb000', emissiveIntensity: 0 });
const greenM = new T.MeshStandardMaterial({ color: '#3ab06a' });
const redM = new T.MeshStandardMaterial({ color: '#e0523a' });

const blockW = 0.30, blockH = 0.20, blockD = 0.16;
const block = new T.Mesh(new T.BoxGeometry(blockW, blockH, blockD), glassM);
block.position.y = 0.20;
root.add(block);
const headM = new T.Mesh(new T.BoxGeometry(0.32, 0.03, 0.18), darkM);
headM.position.y = 0.315;
root.add(headM);
const sump = new T.Mesh(new T.BoxGeometry(0.30, 0.06, 0.16), darkM);
sump.position.y = 0.06;
root.add(sump);
const crankM = new T.Mesh(new T.CylinderGeometry(0.032, 0.032, 0.10, 20), steel);
crankM.rotation.x = Math.PI / 2;
crankM.position.y = 0.09;
root.add(crankM);
const crankPin = new T.Mesh(new T.SphereGeometry(0.011, 12, 12), redM);
root.add(crankPin);
const piston = new T.Mesh(new T.CylinderGeometry(0.055, 0.055, 0.045, 28), steel);
root.add(piston);
const rod = new T.Mesh(new T.BoxGeometry(0.014, 0.12, 0.014), steel);
root.add(rod);
const intakeV = new T.Mesh(new T.CylinderGeometry(0.013, 0.018, 0.05, 14), new T.MeshStandardMaterial({ color: '#3a8de0' }));
intakeV.position.set(-0.05, 0.30, 0);
root.add(intakeV);
const exhaustV = new T.Mesh(new T.CylinderGeometry(0.013, 0.018, 0.05, 14), new T.MeshStandardMaterial({ color: '#e0523a' }));
exhaustV.position.set(0.05, 0.30, 0);
root.add(exhaustV);
const plug = new T.Mesh(new T.SphereGeometry(0.012, 12, 12), sparkM);
plug.position.set(0, 0.295, 0);
root.add(plug);
const pipeI = new T.Mesh(new T.CylinderGeometry(0.016, 0.016, 0.09, 12, 1, true), new T.MeshStandardMaterial({ color: '#3a8de0', transparent: true, opacity: 0.35, side: T.DoubleSide }));
pipeI.rotation.z = 0.7;
pipeI.position.set(-0.10, 0.33, 0);
root.add(pipeI);
const pipeE = new T.Mesh(new T.CylinderGeometry(0.016, 0.016, 0.09, 12, 1, true), new T.MeshStandardMaterial({ color: '#888888', transparent: true, opacity: 0.35, side: T.DoubleSide }));
pipeE.rotation.z = -0.7;
pipeE.position.set(0.10, 0.33, 0);
root.add(pipeE);

const charge = new T.Mesh(new T.CylinderGeometry(0.052, 0.052, 1, 24), blueM.clone());
root.add(charge);
const flame = new T.Mesh(new T.SphereGeometry(0.030, 16, 16), orangeM);
flame.position.set(0, 0.26, 0);
flame.visible = false;
root.add(flame);
const puff = new T.Mesh(new T.SphereGeometry(0.020, 14, 14), greyM);
puff.visible = false;
root.add(puff);

const STROKES = [
  { name: '1. Intake', desc: 'Piston down, intake open, blue fuel air in' },
  { name: '2. Compression', desc: 'Both shut, piston up, charge squeezes' },
  { name: '3. Power', desc: 'Spark flash pushes piston down' },
  { name: '4. Exhaust', desc: 'Exhaust open, piston up, smoke out' }
];
const strokeLabel = aide.spawn('label', { text: STROKES[0].name, position: [0, 0.44, -0.18], size: 0.032 });
const descLabel = aide.spawn('label', { text: STROKES[0].desc, position: [0, 0.395, -0.18], size: 0.025 });

const nextBtn = aide.spawn('box', { size: [0.12, 0.025, 0.06], color: '#ffd400', position: [-0.13, 0.013, 0.14] });
const nextLab = aide.spawn('label', { text: 'Next >', position: [-0.13, 0.055, 0.14], size: 0.027 });
const autoBtn = aide.spawn('box', { size: [0.12, 0.025, 0.06], color: '#3ab06a', position: [0.13, 0.013, 0.14] });
const autoLab = aide.spawn('label', { text: 'Auto: ON', position: [0.13, 0.055, 0.14], size: 0.027 });

const DUR = 2.6;
let stroke = 0, prog = 0, playing = false, autoOn = true, crankA = 0, puffT = 0;
let lastPoke = -10;

function setStrokeUI() {
  strokeLabel.setText(STROKES[stroke].name);
  descLabel.setText(STROKES[stroke].desc);
  autoLab.setText(autoOn ? 'Auto: ON' : 'Auto: OFF');
}
setStrokeUI();

function goNext() {
  if (playing) return;
  playing = true;
  prog = 0;
  puffT = 0;
  aide.sound.tick();
}
function toggleAuto() {
  autoOn = !autoOn;
  setStrokeUI();
  aide.sound.pop();
  if (autoOn && !playing) { playing = true; prog = 0; }
}
aide.panel({ title: '4-Stroke Engine', text: 'Step through Intake, Compression, Power, Exhaust.', buttons: [{ id: 'next', label: 'Next stroke' }, { id: 'auto', label: 'Auto on/off' }], onButton(id) { if (id === 'next') goNext(); if (id === 'auto') toggleAuto(); } });

aide.onPinch((e) => {
  if (e.object === nextBtn) goNext();
  else if (e.object === autoBtn) toggleAuto();
});

function nearBtn(p, b) {
  const dx = p.x - b.position.x, dy = p.y - b.position.y, dz = p.z - b.position.z;
  return (dx * dx + dy * dy + dz * dz) < 0.0036;
}
function checkPoke(now) {
  if (now - lastPoke < 0.6) return;
  for (const k of ['left', 'right']) {
    const h = aide.hands[k];
    if (!h.visible) continue;
    const p = h.joints.indexTip;
    if (nearBtn(p, nextBtn)) { lastPoke = now; goNext(); return; }
    if (nearBtn(p, autoBtn)) { lastPoke = now; toggleAuto(); return; }
  }
}

const TOP = 0.245, BOT = 0.135;
function pistonYFor(s, p) {
  if (s === 0) return TOP + (BOT - TOP) * p;
  if (s === 1) return BOT + (TOP - BOT) * p;
  if (s === 2) return TOP + (BOT - TOP) * p;
  return BOT + (TOP - BOT) * p;
}
aide.emit('built', { model: 'four-stroke', strokes: 4 });

if (autoOn) { playing = true; prog = 0; }

aide.onFrame((dt, t) => {
  checkPoke(t);
  if (playing) {
    prog += dt / DUR;
    crankA += dt * 2.2;
    if (prog >= 1) {
      prog = 0;
      stroke = (stroke + 1) % 4;
      setStrokeUI();
      if (stroke === 2) aide.sound.pop();
      if (stroke === 3) aide.sound.chime();
      if (!autoOn) playing = false;
    }
  } else if (autoOn) { playing = true; prog = 0; }
  const py = pistonYFor(stroke, playing ? prog : 1);
  const pyW = pistonYFor(stroke, 0);
  void pyW;
  piston.position.set(0, py, -0.18);
  const pinY = 0.09 + Math.sin(crankA) * 0.022;
  const pinX = Math.cos(crankA) * 0.022;
  crankM.rotation.y = crankA;
  crankPin.position.set(pinX, pinY, -0.11);
  const midY = (pinY + py) / 2;
  rod.position.set(pinX * 0.3, midY, -0.18);
  const dy = py - pinY;
  rod.scale.y = Math.max(0.5, dy / 0.10);
  rod.rotation.z = -pinX * 4.0;

  const intakeOpen = stroke === 0;
  const exhaustOpen = stroke === 3;
  intakeV.position.y = intakeOpen ? 0.285 : 0.30;
  exhaustV.position.y = exhaustOpen ? 0.285 : 0.30;

  const topY = 0.30, botY = py + 0.023;
  const h = Math.max(0.015, topY - botY);
  charge.position.set(0, botY + h / 2, -0.18);
  charge.scale.set(1, h, 1);
  if (stroke === 0) { charge.material.color.set('#3a8de0'); charge.material.opacity = 0.35 + prog * 0.3; charge.visible = true; }
  else if (stroke === 1) { charge.material.color.set('#2b6fd0'); charge.material.opacity = 0.6; charge.visible = true; }
  else if (stroke === 2) { charge.material.color.set('#ff9a2e'); charge.material.opacity = 0.75; charge.visible = true; }
  else { charge.material.color.set('#9a9a9a'); charge.material.opacity = 0.5 * (1 - prog * 0.7); charge.visible = true; }

  const isPower = stroke === 2;
  flame.visible = isPower && prog < 0.45;
  if (flame.visible) {
    const s = 1 + Math.sin(t * 18) * 0.15;
    flame.scale.set(s, s, s);
    flame.position.set(0, botY + 0.035, -0.18);
    sparkM.emissiveIntensity = 3;
  } else sparkM.emissiveIntensity = 0;

  if (stroke === 3) {
    puff.visible = true;
    puffT += dt;
    const k = playing ? prog : 1;
    puff.position.set(0.05 + k * 0.08, 0.33 + k * 0.06, -0.18);
    const ps = 0.7 + k * 1.1;
    puff.scale.set(ps, ps, ps);
    puff.material.opacity = 0.55 * (1 - k * 0.6);
  } else if (stroke === 0) {
    puff.visible = true;
    const k = playing ? prog : 0.5;
    puff.position.set(-0.10 + k * 0.06, 0.33 - k * 0.03, -0.18);
    puff.scale.set(0.7, 0.7, 0.7);
    puff.material.color.set('#3a8de0');
    puff.material.opacity = 0.5;
  } else { puff.visible = false; puff.material.color.set('#9a9a9a'); }

  nextBtn.position.y = 0.013 + Math.sin(t * 2) * 0.001;
});
